import type { ReactNode } from 'react'

import { Accordion, Icon, useAccordionItemContext } from '@chakra-ui/react'
import type { AccordionRootProps }  from '@chakra-ui/react'
import { Box, List, HStack } from '@chakra-ui/react'

import { olBracketsStyle, olStart } from '~/ui/parts/MyList'

import { useRippleEffect, RippleEffect } from '~/ui/parts/effect/RippleEffect'
import { AiOutlineRightCircle } from 'react-icons/ai'


/** @jsxImportSource @emotion/react */
//import { css } from '@emotion/react'



type AccordionItem = {
  title: ReactNode;
  detail: ReactNode;
}
type AccordionListProp = AccordionRootProps & {
  list: AccordionItem[];
}
export function AccordionList(prop: AccordionListProp) {
  const { list, ...otherProp } = prop;
  
  return (
    <Accordion.Root multiple {...otherProp}>
      {list.map((info, index) => (
        <AccordionItem key={index} index={index} title={info.title} detail={info.detail} />
       ))}
    </Accordion.Root>
  )
}


type AccordionItemProp = AccordionItem & {
  index: number;
}
function AccordionItem(prop: AccordionItemProp) {
  const { index, title, detail } = prop;
  
  const { targetProp, effectProp } = useRippleEffect<HTMLButtonElement>();
  
  return (
    <Accordion.Item value={`${index}`}>
      <Accordion.ItemTrigger fontSize='unset' cursor='pointer' {...targetProp}>
        <List.Root {...olStart(index + 1)}>
          <List.Item {...olBracketsStyle}>
            <HStack gap='0.2em' alignItems='stretch'>
              {/* markerの縦位置がリスと表示の最初の要素の影響を受けるので、空白1文字を先頭に置き、Accordio用のiconはその次とする */}
              <Box>&nbsp;</Box>
              <AccordionIcon />
              {title}
            </HStack>
          </List.Item>
        </List.Root>
        <RippleEffect {...effectProp} />
      </Accordion.ItemTrigger>
      <Accordion.ItemContent className='accordion-item-content' marginLeft='2em' marginBottom='0.25em'>
        <Accordion.ItemBody p='2px'>{detail}</Accordion.ItemBody>
      </Accordion.ItemContent>
    </Accordion.Item>
  )
}

function AccordionIcon() {
  const item = useAccordionItemContext();
  return (
    <Box as='div' display='flex' flexDirection='row' alignItems='start' paddingTop='0.25em'>
      <Icon size='sm'
        transition='transform 0.2s' transform={`rotateZ(${item.expanded ? '90' : '0'}deg)`} transformOrigin='center' 
        >
        <AiOutlineRightCircle />
      </Icon>
    </Box>
  )
}

