import type { ReactNode } from 'react'

import { Box, List, Text } from '@chakra-ui/react'
import type { TextProps } from '@chakra-ui/react'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'



type MyLineBreakProp = TextProps & {
  children: ReactNode;
  center?: boolean;
  bothSides?: boolean;
}
export function MyLineBreak(prop: MyLineBreakProp) {
  const { children, center = false, bothSides = false, ...otherProp } = prop;
  const styleCenter = center ? stylesMyLineBreak.center : undefined;
  const styleBothSides = bothSides ? stylesMyLineBreak.bothSides : undefined;
  
  return (
    <Text as='div' css={[stylesMyLineBreak.base, styleCenter, styleBothSides].flat()} {...otherProp}>
      {children}
    </Text>
  )
}


type MyArrowListProp = {
  list: { target: ReactNode, action: ReactNode }[];
}
export function MyArrowList(prop: MyArrowListProp) {
  const { list } = prop;
  return (
    <Box w='fit-content' m='0.5em 2.0em 0.5em 1.5em'>
      <List.Root>
        {list.map((info, index) => (
          <List.Item key={index}>
            <Box css={[stylesMyLineBreak.base, stylesMyLineBreak.bothSides].flat()}>
              <span>{info.target}</span>
              <Box>
                <span>&nbsp;&rArr;&nbsp;</span>
                <span>{info.action}</span>
              </Box>
            </Box>
          </List.Item>
        ))}
      </List.Root>
    </Box>
  )
}



const stylesMyLineBreak = {
  base: css`
    display: flex;
    flex-wrap: wrap;
  `,
  center: css`
    justify-content: center;
    margin-inline: auto;
    width: fit-content;
  `,
  bothSides: css`
    width: fit-content;
    > *:last-child {
      display: inline-flex;
      justify-content: end;
      flex-grow: 1;
    }
  `
}

