const SceneAtHome = memo(function Introduction() {
  const [openPrelude, setOpenPrelude] = useState<boolean>(false);
  
  // collapsedHeight='2.5rem'は'2.25rem'とかにすると浮動小数点演算の誤差のためか下までスクロールしても--scroll-area-overflow-y-endが1を超えてしまいbottom判定とならない。
  // 値を変える際は注意が必要。(collapseのcontentをmax-heightで開閉状況によらず一定にしても変化しなかったので、アニメーションなどの影響ではなさそう)
  return (
    <Collapsible.Root
      collapsedHeight='2.5rem' justifyItems='center'
        open={openPrelude} onOpenChange={(e) => setOpenPrelude(e.open)}
        >
        <Collapsible.Trigger asChild maxWidth='100%' paddingY='3' display='flex' gap='2' style={{ position: 'sticky', top: 0, marginInline: 'auto' }}>
          <MyYesButton zIndex='1' h={openPrelude ? 'unset' : '5.5em'}>
            <Collapsible.Indicator transition='transform 0.2s' _open={{ transform: 'rotateZ(180deg)' }}>
              <BsArrowDownCircle />
            </Collapsible.Indicator>
            <Collapsible.Context>
              {(api) => (api.open ? '例を閉じる' : (<Box maxWidth='95%' fontSize='clamp(0.75em, 3vw, 1em)'>
                紹介の最後に、うちの子たちと楽しんだ方法の一例を。<br/>
                こちらをクリックして、眺めて頂ければ嬉しいです。<br/>
                (飛ばして本編へ進んでも問題ありません)<br/>
              </Box>))}
            </Collapsible.Context>
          </MyYesButton>
        </Collapsible.Trigger>
        <Collapsible.Content
          _closed={{
            shadow: 'inset 0 -12px 12px -12px var(--shadow-color)',
            shadowColor: 'blackAlpha.500',
          }}
          onClick={() => setOpenPrelude(true)}
          >
          <Prelude />
        </Collapsible.Content>
      </Collapsible.Root>
  )
})


export default SceneAtHome




